"""Separate deterministic compact-page retry-count probe; no query-route/performance claims."""

from __future__ import annotations

import argparse
import json
import os
from pathlib import Path
import subprocess
import sys
import time

HERE = Path(__file__).resolve().parent
sys.path.insert(0, str(HERE.parent))
import run_diagnostic as diagnostic
from analyze_pages import analyze_owner

identity = diagnostic.identity
PLAN = HERE / 'prospective-protocol.json'
MAIN = 'org.eclipse.rdf4j.sail.lmdb.evaluation.CompactPageRetryProbe'
EXPECTED = {
    'valid': True, 'refusedInsertionCount': 1024, 'rows': 2052, 'idChecksum': 87_210,
    'resolverCallsA': 1, 'resolverCallsB': 1025, 'initialRetainedBytes': 2496, 'refusedRetainedBytes': 2496,
    'promotedRetainedBytes': 18_368, 'blockedLedgerBytes': 19_872, 'beforeOwnerCloseBytes': 18_368,
    'afterOwnerCloseBytes': 0, 'processLedgerAfterBytes': 0, 'processLedgerPeakBytes': 19_872,
    'spillCallbacks': 0, 'shedCallbacks': 0, 'queryRouteClaimed': False, 'performanceMeasurement': False,
}
PAGE_EXPECTED = {
    'pageAdmissions': 1, 'pageReleases': 1, 'baseReservationGrants': 1, 'baseReservationRefusals': 0,
    'baseBytesGranted': 512, 'baseBytesObservedBeforeRelease': 512,
    'promotionAttempts': 1025, 'promotionReservationGrants': 1, 'promotionRefusals': 1024,
    'promotionSuccesses': 1, 'promotionBytesGranted': 15_872, 'promotionBytesObservedBeforeRelease': 15_872,
    'factorHits': 1026, 'ordinaryCacheHits': 0, 'firstRefusalKind': 4, 'firstRefusalLedgerBytes': 19_872,
    'snapshotQueryLimitBytes': 20_000, 'snapshotLedgerBytes': 18_368,
}


def sources():
    files = sorted((HERE / 'src').rglob('*.java')) + [Path(__file__).resolve(), HERE / 'protocol.md']
    return {str(path.relative_to(HERE)): identity.sha(path) for path in files}


def prepare():
    parent = diagnostic.read_plan()
    base = diagnostic.read_runtime(parent, 'compact')
    source_map = sources()
    plan = {'format': 1, 'purpose': 'Count persistent non-reclaiming promotion refusals and later recovery',
            'sourceHashes': source_map, 'parentProtocolSha256': identity.sha(diagnostic.PLAN),
            'baseRuntimeFile': str(diagnostic.GENERATED / 'compact/runtime.json'),
            'baseRuntimeSha256': identity.sha(diagnostic.GENERATED / 'compact/runtime.json'),
            'baseRuntime': base, 'sourceIdentity': base['sourceIdentity'] + '+retry-probe-sha256-'
                + identity.canonical_sha(source_map),
            'java': str(diagnostic.JAVA), 'jvmArguments': diagnostic.JVM,
            'javaIdentity': parent['javaIdentity'], 'expected': EXPECTED, 'pageExpected': PAGE_EXPECTED,
            'timeoutSeconds': 30, 'noPerformanceInference': True, 'noQueryRouteClaim': True}
    diagnostic.write_new(PLAN, plan)
    print(json.dumps({'protocol': str(PLAN), 'sha256': identity.sha(PLAN), 'javaExecuted': False}))


def read_plan():
    parent = diagnostic.read_plan()
    plan = json.loads(PLAN.read_text())
    assert plan['sourceHashes'] == sources()
    assert plan['parentProtocolSha256'] == identity.sha(diagnostic.PLAN)
    assert plan['baseRuntimeSha256'] == identity.sha(plan['baseRuntimeFile'])
    assert plan['baseRuntime'] == diagnostic.read_runtime(parent, 'compact')
    assert plan['expected'] == EXPECTED and plan['pageExpected'] == PAGE_EXPECTED
    return plan


def compile_probe():
    plan = read_plan()
    classes = HERE / 'classes'
    classes.mkdir(exist_ok=False)
    argv = [str(diagnostic.JAVA.with_name('javac')), '-proc:none', '-implicit:none', '-encoding', 'UTF-8',
            '--release', '25', '-cp', plan['baseRuntime']['classpath'], '-sourcepath', '', '-d', str(classes)]
    argv += [str(p) for p in sorted((HERE / 'src').rglob('*.java'))]
    diagnostic.write_new(HERE / 'compile-command.json', {'argv': argv, 'cwd': str(diagnostic.ROOT),
                                                        'startedEpochNs': time.time_ns()})
    try:
        with (HERE / 'compile.log').open('xb') as log:
            completed = subprocess.run(argv, cwd=diagnostic.ROOT, stdout=log, stderr=subprocess.STDOUT, timeout=60)
    except subprocess.TimeoutExpired:
        diagnostic.write_new(HERE / 'compile-result.json', {'exitCode': None, 'timedOut': True,
                                                           'finishedEpochNs': time.time_ns()})
        raise
    diagnostic.write_new(HERE / 'compile-result.json', {'exitCode': completed.returncode,
                                                       'finishedEpochNs': time.time_ns()})
    assert completed.returncode == 0, 'Preserve failed compile without replacement'
    emitted = identity.tree_files(classes)
    stem = MAIN.replace('.', '/')
    assert emitted and all(name == stem + '.class' or name.startswith(stem + '$') and name.endswith('.class')
                           for name in emitted)
    for entry in plan['baseRuntime']['manifest']:
        if entry['kind'] == 'tree':
            assert not emitted.keys() & identity.tree_files(entry['path']).keys(), 'Probe shadows a frozen class'
    cp = str(classes) + os.pathsep + plan['baseRuntime']['classpath']
    manifest = identity.classpath_manifest(cp)
    assert len(manifest) == 130 and manifest[1:] == plan['baseRuntime']['manifest']
    (HERE / 'classpath.txt').write_text(cp + '\n')
    diagnostic.write_new(HERE / 'classpath-manifest.json', manifest)
    diagnostic.write_new(HERE / 'runtime.json', {'format': 1, 'protocolSha256': identity.sha(PLAN),
        'sourceIdentity': plan['sourceIdentity'], 'classpath': cp, 'manifest': manifest, 'newClasses': emitted,
        'allOtherArtifactsUnchanged': True, 'diagnosticOnly': True})


def run():
    plan = read_plan()
    runtime = json.loads((HERE / 'runtime.json').read_text())
    assert runtime['protocolSha256'] == identity.sha(PLAN)
    assert runtime['sourceIdentity'] == plan['sourceIdentity']
    assert identity.classpath_manifest(runtime['classpath']) == runtime['manifest']
    assert runtime['manifest'][1:] == plan['baseRuntime']['manifest']
    folder = HERE / 'run'
    folder.mkdir(exist_ok=False)
    pages = folder / 'page-records'
    pages.mkdir()
    jvm = diagnostic.JVM + ['-D' + diagnostic.PROPERTY + '=' + str(pages), '-D' + diagnostic.TRANSPORT + '=dense']
    argv = [str(diagnostic.JAVA)] + jvm + ['-cp', runtime['classpath'], MAIN,
                                         str(folder / 'probe.json'), plan['sourceIdentity']]
    diagnostic.write_new(folder / 'command.json', {'argv': argv, 'cwd': str(diagnostic.ROOT),
        'protocolSha256': identity.sha(PLAN), 'runtimeSha256': identity.sha(HERE / 'runtime.json'),
        'startedEpochNs': time.time_ns()})
    try:
        with (folder / 'console.log').open('xb') as log:
            completed = subprocess.run(argv, cwd=diagnostic.ROOT, stdout=log, stderr=subprocess.STDOUT,
                                       timeout=plan['timeoutSeconds'])
    except subprocess.TimeoutExpired:
        diagnostic.write_new(folder / 'process-result.json', {'exitCode': None, 'timedOut': True,
                                                            'finishedEpochNs': time.time_ns()})
        raise
    diagnostic.write_new(folder / 'process-result.json', {'exitCode': completed.returncode,
                                                         'finishedEpochNs': time.time_ns()})
    assert completed.returncode == 0, 'Preserve failed probe; do not replace its run'
    read_plan()
    assert identity.classpath_manifest(runtime['classpath']) == runtime['manifest'], 'Post-run runtime changed'
    record = json.loads((folder / 'probe.json').read_text())
    expected = {**EXPECTED, **plan['javaIdentity'], 'source': plan['sourceIdentity'], 'jvmArguments': jvm}
    checks = {key: record.get(key) == value for key, value in expected.items()}
    owners = sorted(pages.glob('owner-*.jsonl'))
    assert len(owners) == 1 and owners[0].name == 'owner-1.jsonl'
    owner = analyze_owner(owners[0])
    page_checks = {key: owner['summary'][key] == value for key, value in PAGE_EXPECTED.items()}
    table = owner['finalTable']
    page_checks['oneDenseTwoCellPage'] = table['compactPages'] == 0 and table['densePages'] == 1 \
        and table['occupiedWeakReferenceSlots'] == 2 and table['declaredPageBytes'] == 16_384
    raw_page = json.loads(owners[0].open().readline())
    page_checks['exactOffsets'] = raw_page['occupiedOffsetMask'] == 3
    valid = all(checks.values()) and all(page_checks.values()) and owner['allChecksPassed'] \
        and owner['allGrantedBytesObservedAtExplicitRelease']
    result = {'format': 1, 'valid': valid, 'probeChecks': checks, 'pageChecks': page_checks, 'probe': record,
              'owner': owner, 'scope': 'Deterministic synthetic retry counts only; no route or performance inference.'}
    diagnostic.write_new(HERE / 'analysis.json', result)
    assert valid, 'Retry probe failed validation; preserve records'
    print(json.dumps({'valid': True, 'refusedPromotions': owner['summary']['promotionRefusals'],
                      'successfulRecovery': owner['summary']['promotionSuccesses'],
                      'resolverCalls': record['resolverCallsA'] + record['resolverCallsB'],
                      'factorHits': owner['summary']['factorHits'], 'endLedgerBytes': record['processLedgerAfterBytes']}))


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('action', choices=['prepare', 'compile', 'run'])
    parser.add_argument('--slot-granted', action='store_true')
    args = parser.parse_args()
    if args.action in ('compile', 'run'):
        assert args.slot_granted, 'Probe compile/JVM needs a separate coordinator slot'
    {'prepare': prepare, 'compile': compile_probe, 'run': run}[args.action]()


if __name__ == '__main__':
    main()
